// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  ArrowLeftRightIcon,
  BriefcaseIcon,
  CalculatorIcon,
  CalendarClockIcon,
  ClockIcon,
  EarthIcon,
  HashIcon,
  MoonIcon,
  RepeatIcon,
  SunriseIcon,
  SunsetIcon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CLOCKS,
  CRON,
  CRON_DEFAULT,
  CRON_RESULT,
  CRON_START,
  EPOCH,
  FORMATS,
  FROM_TEXT,
  HEADLINE,
  LOG_RELATIVE,
  MEETING,
  NOW,
  READ_AS,
  SHIFT,
  SHIFT_LABEL,
  SHIFTED,
  TABS,
  TO_TEXT,
  TOTALS,
  formatOffset,
  type Phase,
} from './script'

const TAB_ICONS = [HashIcon, CalculatorIcon, EarthIcon, RepeatIcon]
const PHASE_ICON = {
  morning: SunriseIcon,
  work: BriefcaseIcon,
  evening: SunsetIcon,
  night: MoonIcon,
}
const PHASE_TONE: Record<Phase, string> = {
  morning: 'bg-amber-500/15 text-amber-300',
  work: 'bg-emerald-500/15 text-emerald-300',
  evening: 'bg-orange-500/15 text-orange-300',
  night: 'bg-indigo-500/15 text-indigo-300',
}
const pad = (value: number) => String(value).padStart(2, '0')

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  moveTo,
  click,
  type,
  scramble,
  count,
  wait,
  cursorOut,
}) => {
  const clock = { s: 0 }
  const paint = () => {
    const seconds = Math.floor(clock.s)
    const at = new Date(NOW + seconds * 1000)
    q('clock').textContent =
      `${pad(at.getUTCHours())}:${pad(at.getUTCMinutes())}:${pad(at.getUTCSeconds())}`
    q('now-s').textContent = String(NOW / 1000 + seconds)
    q('now-ms').textContent = String(NOW + Math.floor(clock.s * 1000))
  }
  paint()

  const openTab = (index: number) => {
    move(`tab-${index}`)
    click(`tab-${index}`)
    tl.to(
      qa('tab'),
      { backgroundColor: 'rgba(255,255,255,0)', color: 'rgba(161,161,170,1)', duration: 0.2 },
      '<',
    )
    tl.to(
      q(`tab-${index}`),
      { backgroundColor: 'rgba(255,255,255,0.1)', color: 'rgba(250,250,250,1)', duration: 0.2 },
      '<',
    )
    tl.to(q(`view-${index - 1}`), { opacity: 0, duration: 0.2 }, '<')
    tl.fromTo(
      q(`view-${index}`),
      { opacity: 0, y: 8 },
      { opacity: 1, y: 0, duration: 0.3, ease: 'power2.out', immediateRender: false },
      '<0.1',
    )
  }

  step(0)
  move('ts-input', { at: 0.4, ax: 0.2 })
  click('ts-input')
  tl.to(q('ts-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('ts-text', EPOCH, { speed: 0.06 })
  tl.to(q('read-as'), { opacity: 1, duration: 0.2 })
  tl.fromTo(
    qa('ts-row'),
    { opacity: 0, x: -6 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.08, immediateRender: false },
    '<',
  )

  step(1, '+=1')
  openTab(1)
  move('to-field', { ax: 0.3 })
  click('to-field')
  tl.to(q('to-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('to-text', TO_TEXT, { speed: 0.045 })
  tl.fromTo(
    q('diff-result'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '+=0.1',
  )
  TOTALS.forEach((total, index) =>
    count(`total-${index}`, total.value, {
      at: index === 0 ? '<' : '<0.04',
      duration: 0.9,
      decimals: total.decimals ?? 0,
    }),
  )
  tl.to(
    q(`card-${TOTALS.findIndex((total) => total.emphasis)}`),
    { borderColor: 'rgba(52,211,153,0.6)', duration: 0.3 },
    '+=0.2',
  )

  step(2, '+=0.8')
  openTab(2)
  const start = pos('track', 0.5, 0.5)
  const end = pos('track', (SHIFT + 12) / 24, 0.5)
  moveTo(start.x, start.y)
  click()
  moveTo(end.x, end.y, { duration: 0.9 })
  tl.to(
    q('knob'),
    { left: `${((SHIFT + 12) / 24) * 100}%`, duration: 0.9, ease: 'power2.inOut' },
    '<',
  )
  tl.to(q('fill'), { width: `${(SHIFT / 24) * 100}%`, duration: 0.9, ease: 'power2.inOut' }, '<')
  tl.set(q('shift-label'), { text: SHIFT_LABEL }, '<0.5')
  SHIFTED.forEach((clockAfter, index) => {
    scramble(`zt-${index}`, clockAfter.time, { at: '<', duration: 0.4, chars: '0123456789' })
    if (clockAfter.phase !== CLOCKS[index].phase) {
      tl.to(q(`ph-before-${index}`), { opacity: 0, duration: 0.2 }, '<')
      tl.to(q(`ph-after-${index}`), { opacity: 1, duration: 0.2 }, '<')
    }
    if (clockAfter.nextDay) tl.to(q(`next-${index}`), { opacity: 1, duration: 0.2 }, '<')
    if (clockAfter.date !== CLOCKS[index].date)
      tl.set(q(`zd-${index}`), { text: clockAfter.date }, '<')
  })
  SHIFTED.forEach((clockAfter, index) => {
    if (MEETING.includes(clockAfter.label))
      tl.to(
        q(`zone-${index}`),
        { borderColor: 'rgba(52,211,153,0.6)', duration: 0.3 },
        index === 0 ? '+=0.3' : '<',
      )
  })

  step(3, '+=1')
  openTab(3)
  move('cron-input', { ax: 0.4 })
  click('cron-input')
  tl.to(q('cron-text'), { backgroundColor: 'rgba(56,189,248,0.35)', duration: 0.1 }, '+=0.1')
  tl.set(q('cron-text'), { text: '', backgroundColor: 'rgba(56,189,248,0)' }, '+=0.3')
  type('cron-text', CRON, { speed: 0.08 })
  scramble('cron-desc', CRON_RESULT.description, { at: '+=0.1', duration: 0.6 })
  CRON_RESULT.fields.forEach((field, index) => {
    tl.set(q(`cf-raw-${index}`), { text: field.raw }, '<')
    tl.set(q(`cf-shown-${index}`), { text: field.shown }, '<')
  })
  CRON_RESULT.runs.forEach((run, index) => {
    tl.set(q(`run-${index}`), { text: run.when }, index === 0 ? '<' : '<0.06')
    tl.set(q(`run-rel-${index}`), { text: run.relative }, '<')
    tl.fromTo(
      q(`run-row-${index}`),
      { opacity: 0, x: -6 },
      { opacity: 1, x: 0, duration: 0.25, immediateRender: false },
      '<',
    )
  })
  cursorOut('+=0.4')
  final()
  wait(1.5)

  const total = tl.duration()
  tl.to(clock, { s: total, duration: total, ease: 'none', onUpdate: paint }, 0)
  tl.set(
    [q('view-1'), q('view-2'), q('view-3'), q('read-as'), q('diff-result'), ...qa('ts-row')],
    { opacity: 0 },
    0,
  )
}

function Label({ children }: { children: ReactNode }) {
  return <span className="block text-[8.5px] font-medium text-muted">{children}</span>
}

function TimestampView() {
  return (
    <div data-d="view-0" className="absolute inset-0 flex flex-col gap-2">
      <div className="flex items-center gap-3 rounded-lg border border-line bg-white/[0.03] px-3 py-2">
        <span className="flex size-7 items-center justify-center rounded-md bg-[var(--accent)]/15 text-[var(--accent)]">
          <ClockIcon className="size-4" />
        </span>
        <div className="min-w-0 flex-1">
          <span className="text-[8.5px] text-muted">UTC · UTC{formatOffset(0)}</span>
          <p
            data-d="clock"
            className="font-mono text-[18px] font-semibold leading-6 tabular-nums text-ink"
          />
          <span className="text-[9px] text-muted">
            {new Date(NOW).toLocaleDateString('en-US', { dateStyle: 'full', timeZone: 'UTC' })}
          </span>
        </div>
        <div className="space-y-1">
          {[
            ['Unix seconds', 'now-s'],
            ['Unix milliseconds', 'now-ms'],
          ].map(([label, d]) => (
            <span key={d} className="block rounded-md border border-line bg-canvas/70 px-2 py-0.5">
              <Label>{label}</Label>
              <span data-d={d} className="font-mono text-[9.5px] tabular-nums text-ink" />
            </span>
          ))}
        </div>
      </div>
      <span
        data-d="ts-input"
        className="relative flex h-7 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[11px] text-ink"
      >
        <span data-d="ts-ph" className="absolute left-2 text-muted">
          1743256800, 2026-10-24 10:30, +3d…
        </span>
        <span data-d="ts-text" />
        <span className="ml-px h-3.5 w-px animate-pulse bg-ink-soft" />
      </span>
      <div data-d="read-as" className="flex items-center justify-between text-[9px] opacity-0">
        <span className="flex gap-0.5 rounded-md border border-line p-px">
          {['Auto', 's', 'ms', 'µs', 'ns'].map((unit, index) => (
            <span
              key={unit}
              className={`rounded px-1.5 ${index === 0 ? 'bg-white/10 text-ink' : 'text-muted'}`}
            >
              {unit}
            </span>
          ))}
        </span>
        <span className="text-muted">
          Read as {READ_AS} · <span className="text-ink-soft">{LOG_RELATIVE}</span>
        </span>
      </div>
      <div className="grid grid-cols-2 gap-1">
        {FORMATS.map((format) => (
          <span
            key={format.label}
            data-d="ts-row"
            className="rounded-md border border-line bg-white/[0.03] px-2 py-1 opacity-0"
          >
            <Label>{format.label}</Label>
            <span className="block truncate font-mono text-[9.5px] text-ink">{format.value}</span>
          </span>
        ))}
      </div>
    </div>
  )
}

