function ZonesView() {
  return (
    <div data-d="view-2" className="absolute inset-0 flex flex-col gap-2 opacity-0">
      <div className="rounded-lg border border-line bg-white/[0.03] px-3 py-2">
        <div className="flex justify-between text-[9px]">
          <span className="font-medium text-muted">Shift hours</span>
          <span data-d="shift-label" className="font-medium tabular-nums text-ink">
            No shift
          </span>
        </div>
        <span data-d="track" className="relative mt-2 block h-1 rounded-full bg-white/15">
          <span
            data-d="fill"
            className="absolute left-1/2 top-0 block h-full w-0 rounded-full bg-[var(--accent)]"
          />
          <span
            data-d="knob"
            className="absolute left-1/2 top-1/2 size-3 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-[var(--accent)] bg-canvas"
          />
        </span>
      </div>
      <p className="text-[10px] font-semibold text-ink">
        World clock <span className="font-normal text-muted">({CLOCKS.length})</span>
      </p>
      <div className="grid grid-cols-3 gap-1.5">
        {CLOCKS.map((zone, index) => {
          const Before = PHASE_ICON[zone.phase]
          const After = PHASE_ICON[SHIFTED[index].phase]
          return (
            <div
              key={zone.id}
              data-d={`zone-${index}`}
              className={`rounded-lg border bg-white/[0.03] px-2 py-1.5 ${zone.id === 'UTC' ? 'border-[var(--accent)]/50' : 'border-line'}`}
            >
              <div className="flex items-center gap-1.5">
                <span className="relative size-5 shrink-0">
                  <span
                    data-d={`ph-before-${index}`}
                    className={`absolute inset-0 flex items-center justify-center rounded ${PHASE_TONE[zone.phase]}`}
                  >
                    <Before className="size-3" />
                  </span>
                  <span
                    data-d={`ph-after-${index}`}
                    className={`absolute inset-0 flex items-center justify-center rounded opacity-0 ${PHASE_TONE[SHIFTED[index].phase]}`}
                  >
                    <After className="size-3" />
                  </span>
                </span>
                <span className="min-w-0">
                  <span className="flex items-center gap-1 text-[9.5px] font-semibold text-ink">
                    {zone.label}
                    {zone.id === 'UTC' ? (
                      <span className="rounded bg-white/10 px-1 text-[7.5px] font-medium">You</span>
                    ) : null}
                  </span>
                  <span className="block truncate text-[7.5px] text-muted">{zone.id}</span>
                </span>
              </div>
              <div className="mt-0.5 flex items-end justify-between">
                <span
                  data-d={`zt-${index}`}
                  className="font-mono text-[16px] font-semibold leading-5 text-ink"
                >
                  {zone.time}
                </span>
                <span className="pb-0.5 font-mono text-[8px] text-muted">{zone.delta}</span>
              </div>
              <div className="flex items-center gap-1 text-[7.5px] text-muted">
                <span data-d={`zd-${index}`}>{zone.date}</span>
                <span
                  data-d={`next-${index}`}
                  className="rounded bg-white/10 px-1 text-ink opacity-0"
                >
                  Next day
                </span>
                <span className="ml-auto font-mono">UTC{formatOffset(zone.offset)}</span>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

